WITH web_events_by_session AS (SELECT session_id, COUNT(*) AS cnt, SUM(duration_sec) AS total_duration_sec FROM web_events WHERE page = '/cart' GROUP BY session_id) SELECT sessions.id, sessions.browser, sessions.country, web_events_by_session.cnt, web_events_by_session.total_duration_sec FROM sessions LEFT OUTER JOIN web_events_by_session ON sessions.id = web_events_by_session.session_id WHERE web_events_by_session.total_duration_sec >= 2500;
